def new_values():
    raw = zlib.decompress(base64.b64decode(DATA_B64))
    assert len(raw) == W * H * 2
    return struct.unpack("<%dH" % (W * H), raw)   # bytes little-endian -> valor 16 bits

def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "src/background.h"
    src = open(path, encoding="utf-8", errors="surrogateescape").read()
    m = re.search(r"bg_pixels\s*\[[^\]]*\]\s*=\s*\{", src)
    if not m:
        sys.exit("ERRO: nao achei 'bg_pixels[...] = {' em " + path + "; nada alterado.")
    end = src.index("};", m.end())
    old_body = src[m.end():end]
    n_old = len(re.findall(r"0[xX][0-9a-fA-F]+", old_body))
    print("valores no fundo atual:", n_old)
    if n_old != W * H:
        sys.exit("ERRO: esperava %d valores, achei %d; nada alterado." % (W * H, n_old))
    vals = new_values()
    rows = []
    for y in range(H):
        rows.append("   " + ",".join("0x%04x" % v for v in vals[y * W:(y + 1) * W]) + ",")
    new_body = "\n" + "\n".join(rows) + "\n"
    new_src = src[:m.end()] + new_body + src[end:]
    chk = [int(x, 16) for x in re.findall(r"0[xX][0-9a-fA-F]+", new_src[m.end():new_src.index("};", m.end())])]
    assert tuple(chk) == tuple(vals), "verificacao falhou"
    shutil.copyfile(path, path + ".bak_bg")
    open(path, "w", encoding="utf-8", errors="surrogateescape").write(new_src)
    print("OK: fundo substituido em", path, "(backup:", path + ".bak_bg)")

if __name__ == "__main__":
    main()
